export const FAQ_ITEMS: FaqItem[] = [
  { id: "start-1", category: "start", tag: "Старт", title: "Как подключиться в первый раз?", search: "старт как подключиться в первый раз? старт как подключиться в первый раз? откройте на сайте личный кабинет → активную подписку . на личной странице выберите свою систему и установите предложенный клиент. нажмите кнопку импорта либо скопируйте ссылку и добавьте её из буфера. разрешите создание vpn, обновите профиль и проверьте серверы. выберите сервер с числовой задержкой и подключитесь. ссылка подписки является личным ключом. не отправляйте её другим людям.", answer: "<ol><li>Откройте на сайте <b>личный кабинет → активную подписку</b>.<li>На личной странице выберите свою систему и установите предложенный клиент.<li>Нажмите кнопку импорта либо скопируйте ссылку и добавьте её из буфера.<li>Разрешите создание VPN, обновите профиль и проверьте серверы.<li>Выберите сервер с числовой задержкой и подключитесь.</li></li></li></li></li></ol><div class=\"warning\">Ссылка подписки является личным ключом. Не отправляйте её другим людям." },
  { id: "start-2", category: "start", tag: "Ключ", title: "Где взять ссылку подписки или QR-код?", search: "ключ где взять ссылку подписки или qr-код? ключ где взять ссылку подписки или qr-код? откройте личный кабинет на сайте и выберите действующую подписку. на её личной странице находятся кнопки приложений, импорт, ссылка и иногда qr-код. копируйте ссылку целиком. не делайте публичный скриншот страницы: qr-код тоже может содержать ключ.", answer: "<p>Откройте <b>личный кабинет</b> на сайте и выберите действующую подписку. На её личной странице находятся кнопки приложений, импорт, ссылка и иногда QR-код.<p>Копируйте ссылку целиком. Не делайте публичный скриншот страницы: QR-код тоже может содержать ключ.</p></p>" },
  { id: "apps-3", category: "apps", tag: "Выбор", title: "Какое приложение лучше выбрать?", search: "выбор какое приложение лучше выбрать? выбор какое приложение лучше выбрать? для большинства пользователей: iphone/ipad: сначала incy или happ; android: incy или happ; windows/macos/linux: happ или incy, а для расширенных правил — flclashx; tv: happ или flclashx, если они показаны на личной странице. используйте только клиент, который поддерживается вашей страницей подписки. не выбирайте приложение только по чужому видео.", answer: "<p>Для большинства пользователей:<ul><li><b>iPhone/iPad:</b> сначала INCY или Happ;<li><b>Android:</b> INCY или Happ;<li><b>Windows/macOS/Linux:</b> Happ или INCY, а для расширенных правил — FlClashX;<li><b>TV:</b> Happ или FlClashX, если они показаны на личной странице.</li></li></li></li></ul><p>Используйте только клиент, который поддерживается вашей страницей подписки. Не выбирайте приложение только по чужому видео.</p></p>" },
  { id: "servers-4", category: "servers", tag: "Важно", title: "Почему после установки приложения серверов нет?", search: "важно почему после установки приложения серверов нет? важно почему после установки приложения серверов нет? happ, incy, flclashx и другие — это клиенты , а не отдельные vpn-сервисы. они не выдают доступ сами. нужно импортировать вашу подписку artξmida. после успешного обновления появится список серверов.", answer: "<p>Happ, INCY, FlClashX и другие — это <b>клиенты</b>, а не отдельные VPN-сервисы. Они не выдают доступ сами.<p>Нужно импортировать вашу подписку 3set. После успешного обновления появится список серверов.</p></p>" },
  { id: "start-5", category: "start", tag: "Импорт", title: "Что лучше: кнопка «Добавить» или вставка ссылки?", search: "импорт что лучше: кнопка «добавить» или вставка ссылки? импорт что лучше: кнопка «добавить» или вставка ссылки? сначала используйте кнопку импорта на личной странице — она передаёт ссылку приложению в подходящем формате. если кнопка не открывается, скопируйте ссылку полностью и выберите в клиенте добавить из буфера / import url / subscription . не вставляйте ссылку в поисковую строку браузера и на сайты-конвертеры.", answer: "<p>Сначала используйте кнопку импорта на личной странице — она передаёт ссылку приложению в подходящем формате.<p>Если кнопка не открывается, скопируйте ссылку полностью и выберите в клиенте <b>Добавить из буфера / Import URL / Subscription</b>.<div class=\"warning\">Не вставляйте ссылку в поисковую строку браузера и на сайты-конвертеры.</div></p></p>" },
  { id: "start-6", category: "start", tag: "QR", title: "Как импортировать подписку через QR-код?", search: "qr как импортировать подписку через qr-код? qr как импортировать подписку через qr-код? откройте qr-код на другом устройстве или компьютере. в клиенте выберите сканирование qr. разрешите доступ к камере. после импорта сразу обновите профиль. не фотографируйте qr-код для отправки знакомым: он может давать полный доступ к подписке.", answer: "<ol><li>Откройте QR-код на другом устройстве или компьютере.<li>В клиенте выберите сканирование QR.<li>Разрешите доступ к камере.<li>После импорта сразу обновите профиль.</li></li></li></li></ol><p>Не фотографируйте QR-код для отправки знакомым: он может давать полный доступ к подписке.</p>" },
  { id: "apps-7", category: "apps", tag: "iOS", title: "Полная настройка на iPhone или iPad", search: "ios полная настройка на iphone или ipad ios полная настройка на iphone или ipad откройте личную страницу подписки в safari. выберите incy или happ и установите приложение из app store. вернитесь в safari и нажмите кнопку добавления подписки. подтвердите открытие приложения и разрешите добавление vpn-конфигурации. обновите профиль, выберите сервер и включите vpn. при первом подключении ios показывает системное окно — это нормальное разрешение на создание vpn.", answer: "<ol><li>Откройте личную страницу подписки в Safari.<li>Выберите INCY или Happ и установите приложение из App Store.<li>Вернитесь в Safari и нажмите кнопку добавления подписки.<li>Подтвердите открытие приложения и разрешите добавление VPN-конфигурации.<li>Обновите профиль, выберите сервер и включите VPN.</li></li></li></li></li></ol><p>При первом подключении iOS показывает системное окно — это нормальное разрешение на создание VPN.</p>" },
  { id: "apps-8", category: "apps", tag: "App Store", title: "Приложение недоступно в App Store моего региона", search: "app store приложение недоступно в app store моего региона app store приложение недоступно в app store моего региона не скачивайте случайный ipa. сначала выберите другое приложение, предложенное на личной странице: например, incy вместо happ. смена региона apple id может требовать отсутствия денег на балансе, незавершённых возвратов и активных подписок. проще использовать доступную официальную альтернативу.", answer: "<p>Не скачивайте случайный IPA. Сначала выберите другое приложение, предложенное на личной странице: например, INCY вместо Happ.<p>Смена региона Apple ID может требовать отсутствия денег на балансе, незавершённых возвратов и активных подписок. Проще использовать доступную официальную альтернативу.</p></p>" },
  { id: "apps-9", category: "apps", tag: "Android", title: "Полная настройка на Android", search: "android полная настройка на android android полная настройка на android откройте страницу подписки в браузере. установите incy, happ или другой предложенный клиент через google play либо официальную ссылку. нажмите импорт на странице или добавьте url из буфера. разрешите vpn-подключение. отключите экономию батареи для клиента, если соединение обрывается в фоне. apk устанавливайте только из официального источника, указанного на странице.", answer: "<ol><li>Откройте страницу подписки в браузере.<li>Установите INCY, Happ или другой предложенный клиент через Google Play либо официальную ссылку.<li>Нажмите импорт на странице или добавьте URL из буфера.<li>Разрешите VPN-подключение.<li>Отключите экономию батареи для клиента, если соединение обрывается в фоне.</li></li></li></li></li></ol><p>APK устанавливайте только из официального источника, указанного на странице.</p>" },
  { id: "apps-10", category: "apps", tag: "Windows", title: "Полная настройка на Windows", search: "windows полная настройка на windows windows полная настройка на windows скачайте happ, incy или flclashx с личной страницы. установите приложение и разрешите запуск в брандмауэре. добавьте подписку по url и обновите её. для большинства программ включите tun . system proxy подходит только приложениям, которые его учитывают. выберите сервер и проверьте открытие сайтов.", answer: "<ol><li>Скачайте Happ, INCY или FlClashX с личной страницы.<li>Установите приложение и разрешите запуск в брандмауэре.<li>Добавьте подписку по URL и обновите её.<li>Для большинства программ включите <b>TUN</b>. System Proxy подходит только приложениям, которые его учитывают.<li>Выберите сервер и проверьте открытие сайтов.</li></li></li></li></li></ol>" },
  { id: "apps-11", category: "apps", tag: "macOS", title: "Полная настройка на macOS", search: "macos полная настройка на macos macos полная настройка на macos выберите клиент для macos на личной странице. установите его из app store или официального релиза. импортируйте подписку и разрешите системное vpn-расширение. обновите профиль и включите tun/vpn. на apple silicon некоторые iphone-приложения доступны и на mac, но нативная версия обычно удобнее.", answer: "<ol><li>Выберите клиент для macOS на личной странице.<li>Установите его из App Store или официального релиза.<li>Импортируйте подписку и разрешите системное VPN-расширение.<li>Обновите профиль и включите TUN/VPN.</li></li></li></li></ol><p>На Apple Silicon некоторые iPhone-приложения доступны и на Mac, но нативная версия обычно удобнее.</p>" },
  { id: "apps-12", category: "apps", tag: "Linux", title: "Полная настройка на Linux", search: "linux полная настройка на linux linux полная настройка на linux выберите сборку для своей архитектуры и формата системы: appimage, deb или rpm. установите необходимые зависимости, указанные официальным проектом. добавьте url подписки и обновите профиль. включите tun; система может запросить права администратора. для начинающих удобнее happ/incy, а для правил — flclashx.", answer: "<ol><li>Выберите сборку для своей архитектуры и формата системы: AppImage, deb или rpm.<li>Установите необходимые зависимости, указанные официальным проектом.<li>Добавьте URL подписки и обновите профиль.<li>Включите TUN; система может запросить права администратора.</li></li></li></li></ol><p>Для начинающих удобнее Happ/INCY, а для правил — FlClashX.</p>" },
  { id: "apps-13", category: "apps", tag: "Happ", title: "Как добавить подписку в Happ?", search: "happ как добавить подписку в happ? happ как добавить подписку в happ? скопируйте ссылку подписки. откройте happ и нажмите + . выберите добавление из буфера или manual input и вставьте url. нажмите обновление рядом с названием профиля. запустите проверку задержки и подключитесь. для ссылок happ:// нужна актуальная версия приложения.", answer: "<ol><li>Скопируйте ссылку подписки.<li>Откройте Happ и нажмите <b>+</b>.<li>Выберите добавление из буфера или Manual Input и вставьте URL.<li>Нажмите обновление рядом с названием профиля.<li>Запустите проверку задержки и подключитесь.</li></li></li></li></li></ol><p>Для ссылок <code>happ://</code> нужна актуальная версия приложения.</p>" },
  { id: "servers-14", category: "servers", tag: "Happ", title: "Как обновить профиль и подробно проверить серверы в Happ?", search: "happ как обновить профиль и подробно проверить серверы в happ? happ как обновить профиль и подробно проверить серверы в happ? откройте happ и найдите профиль artξmida. нажмите значок круговой стрелки рядом с профилем и дождитесь окончания обновления. откройте список серверов, нажав название текущего сервера. нажмите значок молнии, часов или пункт проверки задержки. если приложение предлагает методы, выберите http get . подождите 10–20 секунд. выберите сервер, рядом с которым появилось число в ms . n/a / timeout означает, что сервер не ответил из текущей сети. попробуйте другой сервер и смените wi‑fi на мобильный интернет или наоборот.", answer: "<ol><li>Откройте Happ и найдите профиль 3set.<li>Нажмите значок круговой стрелки рядом с профилем и дождитесь окончания обновления.<li>Откройте список серверов, нажав название текущего сервера.<li>Нажмите значок молнии, часов или пункт проверки задержки.<li>Если приложение предлагает методы, выберите <b>HTTP GET</b>.<li>Подождите 10–20 секунд. Выберите сервер, рядом с которым появилось число в <b>ms</b>.</li></li></li></li></li></li></ol><p><b>N/A / timeout</b> означает, что сервер не ответил из текущей сети. Попробуйте другой сервер и смените Wi‑Fi на мобильный интернет или наоборот.</p>" },
  { id: "settings-15", category: "settings", tag: "Happ", title: "Какие настройки Routing выбрать в Happ?", search: "happ какие настройки routing выбрать в happ? happ какие настройки routing выбрать в happ? оставляйте профиль, заданный подпиской. для обычного использования нужен автоматический/рекомендованный routing. rule / smart: рекомендуемый режим; global: весь трафик через vpn, полезно для проверки; direct: без vpn. если соединение не запускается, временно отключите пользовательские правила и проверьте ещё раз.", answer: "<p>Оставляйте профиль, заданный подпиской. Для обычного использования нужен автоматический/рекомендованный routing.<ul><li><b>Rule / Smart:</b> рекомендуемый режим;<li><b>Global:</b> весь трафик через VPN, полезно для проверки;<li><b>Direct:</b> без VPN.</li></li></li></ul><p>Если соединение не запускается, временно отключите пользовательские правила и проверьте ещё раз.</p></p>" },
  { id: "apps-16", category: "apps", tag: "INCY", title: "Как добавить подписку в INCY?", search: "incy как добавить подписку в incy? incy как добавить подписку в incy? установите incy по ссылке на личной странице. нажмите кнопку открытия в incy либо скопируйте url. в приложении выберите добавление подписки из буфера/url. разрешите vpn, обновите профиль и выберите сервер. incy является клиентом: без вашей подписки список серверов будет пустым.", answer: "<ol><li>Установите INCY по ссылке на личной странице.<li>Нажмите кнопку открытия в INCY либо скопируйте URL.<li>В приложении выберите добавление подписки из буфера/URL.<li>Разрешите VPN, обновите профиль и выберите сервер.</li></li></li></li></ol><p>INCY является клиентом: без вашей подписки список серверов будет пустым.</p>" },
  { id: "devices-17", category: "devices", tag: "INCY", title: "INCY пишет «app not supported» или не проходит лимит устройств", search: "incy incy пишет «app not supported» или не проходит лимит устройств incy incy пишет «app not supported» или не проходит лимит устройств откройте настройки incy и включите передачу hwid / device id / идентификатора устройства , если такой переключатель доступен. затем обновите подписку. если лимит уже заполнен, сначала удалите старое устройство в личном кабинете.", answer: "<p>Откройте настройки INCY и включите передачу <b>HWID / Device ID / идентификатора устройства</b>, если такой переключатель доступен. Затем обновите подписку.<p>Если лимит уже заполнен, сначала удалите старое устройство в личном кабинете.</p></p>" },
  { id: "apps-18", category: "apps", tag: "FlClashX", title: "Как настроить FlClashX?", search: "flclashx как настроить flclashx? flclashx как настроить flclashx? откройте profiles / конфигурации . нажмите + → url, задайте название и вставьте подписку. загрузите профиль. в proxies выберите сервер или автоматическую группу. вернитесь на dashboard, включите start и tun. режим rule подходит большинству пользователей; global используйте для диагностики.", answer: "<ol><li>Откройте <b>Profiles / Конфигурации</b>.<li>Нажмите + → URL, задайте название и вставьте подписку.<li>Загрузите профиль.<li>В <b>Proxies</b> выберите сервер или автоматическую группу.<li>Вернитесь на Dashboard, включите <b>Start</b> и TUN.</li></li></li></li></li></ol><p>Режим Rule подходит большинству пользователей; Global используйте для диагностики.</p>" },
  { id: "apps-19", category: "apps", tag: "Shadowrocket", title: "Как настроить Shadowrocket?", search: "shadowrocket как настроить shadowrocket? shadowrocket как настроить shadowrocket? нажмите +. в type выберите subscribe . вставьте url подписки, сохраните и обновите группу. выберите сервер и включите vpn. оставьте режим rule/config. global направляет всё через сервер и может мешать локальным сервисам.", answer: "<ol><li>Нажмите +.<li>В Type выберите <b>Subscribe</b>.<li>Вставьте URL подписки, сохраните и обновите группу.<li>Выберите сервер и включите VPN.</li></li></li></li></ol><p>Оставьте режим Rule/Config. Global направляет всё через сервер и может мешать локальным сервисам.</p>" },
  { id: "settings-20", category: "settings", tag: "v2RayTun", title: "Как настроить v2RayTun?", search: "v2raytun как настроить v2raytun? v2raytun как настроить v2raytun? откройте кнопку импорта с личной страницы либо нажмите +. вставьте ссылку подписки. разрешите создание vpn. обновите список, выберите сервер и включите соединение. после продления обновляйте существующую подписку, а не создавайте множество копий.", answer: "<ol><li>Откройте кнопку импорта с личной страницы либо нажмите +.<li>Вставьте ссылку подписки.<li>Разрешите создание VPN.<li>Обновите список, выберите сервер и включите соединение.</li></li></li></li></ol><p>После продления обновляйте существующую подписку, а не создавайте множество копий.</p>" },
  { id: "apps-21", category: "apps", tag: "v2rayN", title: "Как настроить v2rayN на компьютере?", search: "v2rayn как настроить v2rayn на компьютере? v2rayn как настроить v2rayn на компьютере? откройте subscriptions → subscription group settings. добавьте имя и url. выберите update all subscriptions. выделите сервер. включите set system proxy или tun. если браузер работает, а отдельная программа нет, используйте tun вместо system proxy.", answer: "<ol><li>Откройте Subscriptions → Subscription group settings.<li>Добавьте имя и URL.<li>Выберите Update all subscriptions.<li>Выделите сервер.<li>Включите Set system proxy или TUN.</li></li></li></li></li></ol><p>Если браузер работает, а отдельная программа нет, используйте TUN вместо System Proxy.</p>" },
  { id: "errors-22", category: "errors", tag: "Happ", title: "Happ не работает, не запускается или не подключается", search: "happ happ не работает, не запускается или не подключается happ happ не работает, не запускается или не подключается проверьте интернет без vpn и закройте другие vpn-клиенты. обновите happ и профиль подписки. проверьте серверы через http get и выберите доступный. включите tun; для проверки переключите rule на global. смените wi‑fi на мобильный интернет или наоборот. если проблема остаётся, импортируйте подписку в incy.", answer: "<ol><li>Проверьте интернет без VPN и закройте другие VPN-клиенты.<li>Обновите Happ и профиль подписки.<li>Проверьте серверы через HTTP GET и выберите доступный.<li>Включите TUN; для проверки переключите Rule на Global.<li>Смените Wi‑Fi на мобильный интернет или наоборот.<li>Если проблема остаётся, импортируйте подписку в INCY.</li></li></li></li></li></li></ol>" },
  { id: "errors-23", category: "errors", tag: "Ссылка", title: "Ошибка «невалидная ссылка» или invalid subscription link format", search: "ссылка ошибка «невалидная ссылка» или invalid subscription link format ссылка ошибка «невалидная ссылка» или invalid subscription link format обновите клиент. скопируйте ссылку заново и целиком. удалите пробелы и переносы, если они появились. импортируйте как subscription url , а не как один сервер. попробуйте кнопку открытия на личной странице. не конвертируйте ссылку сторонними сайтами.", answer: "<ol><li>Обновите клиент.<li>Скопируйте ссылку заново и целиком.<li>Удалите пробелы и переносы, если они появились.<li>Импортируйте как <b>Subscription URL</b>, а не как один сервер.<li>Попробуйте кнопку открытия на личной странице.</li></li></li></li></li></ol><p>Не конвертируйте ссылку сторонними сайтами.</p>" },
  { id: "errors-24", category: "errors", tag: "Импорт", title: "Happ пишет encrypted, parsing error или ошибка расшифровки", search: "импорт happ пишет encrypted, parsing error или ошибка расшифровки импорт happ пишет encrypted, parsing error или ошибка расшифровки обычно клиент устарел либо ссылка скопирована не полностью. установите последнюю официальную версию happ. удалите неудачный профиль. скопируйте ссылку заново и добавьте из буфера. если ошибка остаётся, попробуйте incy.", answer: "<p>Обычно клиент устарел либо ссылка скопирована не полностью.<ol><li>Установите последнюю официальную версию Happ.<li>Удалите неудачный профиль.<li>Скопируйте ссылку заново и добавьте из буфера.<li>Если ошибка остаётся, попробуйте INCY.</li></li></li></li></ol></p>" },
  { id: "errors-25", category: "errors", tag: "xrayCore", title: "Критическая ошибка xrayCore или core crashed", search: "xraycore критическая ошибка xraycore или core crashed xraycore критическая ошибка xraycore или core crashed обновите приложение и подписку. полностью закройте клиент и перезагрузите устройство. удалите только профиль и импортируйте его заново. переключите tun/system proxy. временно попробуйте другой клиент. для поддержки приложите видео и версию приложения.", answer: "<ol><li>Обновите приложение и подписку.<li>Полностью закройте клиент и перезагрузите устройство.<li>Удалите только профиль и импортируйте его заново.<li>Переключите TUN/System Proxy.<li>Временно попробуйте другой клиент.</li></li></li></li></li></ol><p>Для поддержки приложите видео и версию приложения.</p>" },
  { id: "errors-26", category: "errors", tag: "Соединение", title: "VPN сразу отключается после нажатия кнопки", search: "соединение vpn сразу отключается после нажатия кнопки соединение vpn сразу отключается после нажатия кнопки закройте другие vpn, антивирусные веб-фильтры и прокси; разрешите создание системного vpn; обновите профиль; выберите другой сервер; перезапустите устройство. на android также отключите экономию батареи для клиента.", answer: "<ul><li>закройте другие VPN, антивирусные веб-фильтры и прокси;<li>разрешите создание системного VPN;<li>обновите профиль;<li>выберите другой сервер;<li>перезапустите устройство.</li></li></li></li></li></ul><p>На Android также отключите экономию батареи для клиента.</p>" },
  { id: "errors-27", category: "errors", tag: "Интернет", title: "VPN подключён, но интернет не работает", search: "интернет vpn подключён, но интернет не работает интернет vpn подключён, но интернет не работает проверьте интернет без vpn. смените сервер. переключите сеть wi‑fi ↔ мобильная. включите tun/vpn вместо system proxy. для теста переключите rule на global. верните настройки dns и routing к значениям подписки.", answer: "<ol><li>Проверьте интернет без VPN.<li>Смените сервер.<li>Переключите сеть Wi‑Fi ↔ мобильная.<li>Включите TUN/VPN вместо System Proxy.<li>Для теста переключите Rule на Global.<li>Верните настройки DNS и routing к значениям подписки.</li></li></li></li></li></li></ol>" },
  { id: "start-28", category: "start", tag: "IP", title: "Подключение включено, но IP-адрес не изменился", search: "ip подключение включено, но ip-адрес не изменился ip подключение включено, но ip-адрес не изменился возможно, приложение работает только как system proxy, а проверяющий браузер или программа его игнорирует. включите tun/vpn , переподключитесь и откройте проверку ip в новой приватной вкладке. также убедитесь, что выбран не direct.", answer: "<p>Возможно, приложение работает только как System Proxy, а проверяющий браузер или программа его игнорирует. Включите <b>TUN/VPN</b>, переподключитесь и откройте проверку IP в новой приватной вкладке.<p>Также убедитесь, что выбран не Direct.</p></p>" },
  { id: "settings-29", category: "settings", tag: "DNS", title: "Ошибка DNS, сайты не находятся по имени", search: "dns ошибка dns, сайты не находятся по имени dns ошибка dns, сайты не находятся по имени верните dns к автоматическому или значению из профиля. отключите сторонние dns-фильтры, private dns и блокировщики для проверки. перезапустите vpn. смените сервер и сеть. не задавайте случайные dns-адреса из видео: это может сломать маршрутизацию.", answer: "<ol><li>Верните DNS к автоматическому или значению из профиля.<li>Отключите сторонние DNS-фильтры, Private DNS и блокировщики для проверки.<li>Перезапустите VPN.<li>Смените сервер и сеть.</li></li></li></li></ol><p>Не задавайте случайные DNS-адреса из видео: это может сломать маршрутизацию.</p>" },
  { id: "apps-30", category: "apps", tag: "Сервис", title: "VPN работает, но один сайт или приложение не открывается", search: "сервис vpn работает, но один сайт или приложение не открывается сервис vpn работает, но один сайт или приложение не открывается полностью закройте проблемное приложение и откройте после vpn; смените сервер или страну; переключите rule → global для проверки; убедитесь, что приложение не исключено из vpn; попробуйте другой клиент. если global помогает, проблема связана с правилом маршрутизации.", answer: "<ul><li>полностью закройте проблемное приложение и откройте после VPN;<li>смените сервер или страну;<li>переключите Rule → Global для проверки;<li>убедитесь, что приложение не исключено из VPN;<li>попробуйте другой клиент.</li></li></li></li></li></ul><p>Если Global помогает, проблема связана с правилом маршрутизации.</p>" },
  { id: "settings-31", category: "settings", tag: "TUN", title: "В браузере работает, а в приложениях нет — или наоборот", search: "tun в браузере работает, а в приложениях нет — или наоборот tun в браузере работает, а в приложениях нет — или наоборот это типичный признак неправильного режима: system proxy охватывает не все программы; tun/vpn перехватывает почти весь трафик устройства. включите tun. на android проверьте список приложений в per-app routing.", answer: "<p>Это типичный признак неправильного режима:<ul><li><b>System Proxy</b> охватывает не все программы;<li><b>TUN/VPN</b> перехватывает почти весь трафик устройства.</li></li></ul><p>Включите TUN. На Android проверьте список приложений в per-app routing.</p></p>" },
  { id: "servers-32", category: "servers", tag: "Пинг", title: "Серверы показывают N/A, timeout или бесконечный пинг", search: "пинг серверы показывают n/a, timeout или бесконечный пинг пинг серверы показывают n/a, timeout или бесконечный пинг откройте в приложении список серверов , нажав название выбранной локации. найдите значок молнии, спидометра, часов или пункт delay / latency / проверить задержку . если есть выбор метода, используйте http get . подождите 10–20 секунд и попробуйте серверы, где появилось число в ms. если n/a показывают все серверы, обновите профиль и смените wi‑fi на мобильную сеть или наоборот. на время проверки отключите пользовательский dns и сложные правила маршрутизации. n/a означает отсутствие ответа из текущей сети, а не обязательно поломку подписки. в разделе «диагностика» есть наглядная инструкция с выбором конкретного приложения.", answer: "<ol><li>Откройте в приложении <b>список серверов</b>, нажав название выбранной локации.<li>Найдите значок молнии, спидометра, часов или пункт <b>Delay / Latency / Проверить задержку</b>.<li>Если есть выбор метода, используйте <b>HTTP GET</b>.<li>Подождите 10–20 секунд и попробуйте серверы, где появилось число в ms.<li>Если N/A показывают все серверы, обновите профиль и смените Wi‑Fi на мобильную сеть или наоборот.<li>На время проверки отключите пользовательский DNS и сложные правила маршрутизации.</li></li></li></li></li></li></ol><p>N/A означает отсутствие ответа из текущей сети, а не обязательно поломку подписки.<p>В разделе «Диагностика» есть наглядная инструкция с выбором конкретного приложения.</p></p>" },
  { id: "servers-33", category: "servers", tag: "Скорость", title: "Низкая скорость или высокий пинг", search: "скорость низкая скорость или высокий пинг скорость низкая скорость или высокий пинг измерьте скорость без vpn. проверьте задержку всех серверов. выберите ближайший доступный сервер. сравните wi‑fi и мобильную сеть. попробуйте другой клиент и время суток. минимальный пинг не всегда даёт максимальную скорость, поэтому проверьте 2–3 лучших сервера.", answer: "<ol><li>Измерьте скорость без VPN.<li>Проверьте задержку всех серверов.<li>Выберите ближайший доступный сервер.<li>Сравните Wi‑Fi и мобильную сеть.<li>Попробуйте другой клиент и время суток.</li></li></li></li></li></ol><p>Минимальный пинг не всегда даёт максимальную скорость, поэтому проверьте 2–3 лучших сервера.</p>" },
  { id: "servers-34", category: "servers", tag: "Выбор", title: "Как правильно выбрать сервер?", search: "выбор как правильно выбрать сервер? выбор как правильно выбрать сервер? начните с автоматической группы или сервера с минимальной числовой задержкой. затем проверьте нужные сайты. для повседневной работы выбирайте стабильность, а не только страну. если сервис не открывается — смените сервер.", answer: "<p>Начните с автоматической группы или сервера с минимальной числовой задержкой. Затем проверьте нужные сайты.<p>Для повседневной работы выбирайте стабильность, а не только страну. Если сервис не открывается — смените сервер.</p></p>" },
  { id: "servers-35", category: "servers", tag: "Сеть", title: "На Wi‑Fi работает, а на мобильном интернете нет", search: "сеть на wi‑fi работает, а на мобильном интернете нет сеть на wi‑fi работает, а на мобильном интернете нет операторы фильтруют трафик по-разному. в проблемной сети: обновите профиль; проверьте все серверы; переключите клиент; включите tun; проверьте, не задан ли private dns. поддержке сообщите оператора и регион.", answer: "<p>Операторы фильтруют трафик по-разному. В проблемной сети:<ol><li>обновите профиль;<li>проверьте все серверы;<li>переключите клиент;<li>включите TUN;<li>проверьте, не задан ли Private DNS.</li></li></li></li></li></ol><p>Поддержке сообщите оператора и регион.</p></p>" },
  { id: "settings-36", category: "settings", tag: "Батарея", title: "VPN отключается, когда экран погас или приложение свернули", search: "батарея vpn отключается, когда экран погас или приложение свернули батарея vpn отключается, когда экран погас или приложение свернули android: отключите оптимизацию батареи, разрешите автозапуск и фоновую работу, при необходимости закрепите клиент в недавних. iphone: не выгружайте клиент жестом постоянно; отключите режим низкого энергопотребления для проверки.", answer: "<p><b>Android:</b> отключите оптимизацию батареи, разрешите автозапуск и фоновую работу, при необходимости закрепите клиент в недавних.<p><b>iPhone:</b> не выгружайте клиент жестом постоянно; отключите режим низкого энергопотребления для проверки.</p></p>" },
  { id: "settings-37", category: "settings", tag: "Разрешение", title: "Что означает запрос «Добавить конфигурацию VPN»?", search: "разрешение что означает запрос «добавить конфигурацию vpn»? разрешение что означает запрос «добавить конфигурацию vpn»? это системное разрешение ios, android, windows или macos на создание vpn-туннеля. без него клиент не сможет работать. подтверждайте запрос только внутри официально установленного приложения. telegram-код или пароль от аккаунта для этого не нужны.", answer: "<p>Это системное разрешение iOS, Android, Windows или macOS на создание VPN-туннеля. Без него клиент не сможет работать.<p>Подтверждайте запрос только внутри официально установленного приложения. Telegram-код или пароль от аккаунта для этого не нужны.</p></p>" },
  { id: "apps-38", category: "apps", tag: "Windows", title: "Windows Defender или антивирус блокирует клиент", search: "windows windows defender или антивирус блокирует клиент windows windows defender или антивирус блокирует клиент сначала убедитесь, что файл скачан с официального источника. разрешите приложению работу в брандмауэре для частных сетей. не отключайте антивирус полностью. если блокируется tun-драйвер, переустановите официальный клиент и запустите установку драйвера с правами администратора.", answer: "<p>Сначала убедитесь, что файл скачан с официального источника. Разрешите приложению работу в брандмауэре для частных сетей.<p>Не отключайте антивирус полностью. Если блокируется TUN-драйвер, переустановите официальный клиент и запустите установку драйвера с правами администратора.</p></p>" },
  { id: "settings-39", category: "settings", tag: "Режим", title: "Что выбрать: TUN, VPN или System Proxy?", search: "режим что выбрать: tun, vpn или system proxy? режим что выбрать: tun, vpn или system proxy? телефон: используйте vpn/tun. компьютер: tun надёжнее и охватывает больше программ; system proxy проще, но работает не со всеми приложениями. если нет специальных требований, выбирайте tun.", answer: "<p><b>Телефон:</b> используйте VPN/TUN.<p><b>Компьютер:</b> TUN надёжнее и охватывает больше программ; System Proxy проще, но работает не со всеми приложениями.<p>Если нет специальных требований, выбирайте TUN.</p></p></p>" },
  { id: "settings-40", category: "settings", tag: "Routing", title: "Что выбрать: Rule, Global или Direct?", search: "routing что выбрать: rule, global или direct? routing что выбрать: rule, global или direct? rule: рекомендуемый умный режим; global: весь трафик через vpn, полезно для проверки; direct: весь трафик напрямую, vpn фактически не используется. после диагностики вернитесь на rule.", answer: "<ul><li><b>Rule:</b> рекомендуемый умный режим;<li><b>Global:</b> весь трафик через VPN, полезно для проверки;<li><b>Direct:</b> весь трафик напрямую, VPN фактически не используется.</li></li></li></ul><p>После диагностики вернитесь на Rule.</p>" },
  { id: "start-41", category: "start", tag: "Обновление", title: "Нужно ли включать автообновление подписки?", search: "обновление нужно ли включать автообновление подписки? обновление нужно ли включать автообновление подписки? да, если клиент поддерживает эту функцию. подходящий интервал — несколько часов или один раз в день. слишком частое обновление не ускоряет vpn. после оплаты или изменения серверов выполните ручное обновление один раз.", answer: "<p>Да, если клиент поддерживает эту функцию. Подходящий интервал — несколько часов или один раз в день.<p>Слишком частое обновление не ускоряет VPN. После оплаты или изменения серверов выполните ручное обновление один раз.</p></p>" },
  { id: "start-42", category: "start", tag: "Обновление", title: "Как обновить подписку?", search: "обновление как обновить подписку? обновление как обновить подписку? найдите профиль artξmida в приложении и нажмите значок обновления, refresh или update subscription. если обновление не проходит, отключите vpn, проверьте обычный интернет, смените сеть и повторите.", answer: "<p>Найдите профиль 3set в приложении и нажмите значок обновления, Refresh или Update subscription.<p>Если обновление не проходит, отключите VPN, проверьте обычный интернет, смените сеть и повторите.</p></p>" },
  { id: "subscription-43", category: "subscription", tag: "Срок", title: "Как понять, что подписка закончилась или закончился трафик?", search: "срок как понять, что подписка закончилась или закончился трафик? срок как понять, что подписка закончилась или закончился трафик? проверьте статус в личном кабинете сайта. в клиенте могут появиться ошибки обновления, пустой список или все серверы перестанут подключаться. после продления обновите существующий профиль. не создавайте новую копию без необходимости.", answer: "<p>Проверьте статус в личном кабинете сайта. В клиенте могут появиться ошибки обновления, пустой список или все серверы перестанут подключаться.<p>После продления обновите существующий профиль. Не создавайте новую копию без необходимости.</p></p>" },
  { id: "subscription-44", category: "subscription", tag: "Оплата", title: "Оплата прошла, но подписка не продлилась", search: "оплата оплата прошла, но подписка не продлилась оплата оплата прошла, но подписка не продлилась подождите несколько минут и обновите личный кабинет. проверьте статус платежа в банке. не оплачивайте второй раз сразу. отправьте поддержке дату, сумму и идентификатор операции; закройте на скриншоте лишние данные.", answer: "<ol><li>Подождите несколько минут и обновите личный кабинет.<li>Проверьте статус платежа в банке.<li>Не оплачивайте второй раз сразу.<li>Отправьте поддержке дату, сумму и идентификатор операции; закройте на скриншоте лишние данные.</li></li></li></li></ol>" },
  { id: "subscription-45", category: "subscription", tag: "Продление", title: "Что делать после продления?", search: "продление что делать после продления? продление что делать после продления? откройте уже добавленный профиль и нажмите обновить . повторно импортировать ссылку обычно не нужно. если в личном кабинете или боте явно создан новый ключ, удалите старый профиль и импортируйте новый.", answer: "<p>Откройте уже добавленный профиль и нажмите <b>обновить</b>. Повторно импортировать ссылку обычно не нужно.<p>Если в личном кабинете или боте явно создан новый ключ, удалите старый профиль и импортируйте новый.</p></p>" },
  { id: "start-46", category: "start", tag: "Ключ", title: "Что произойдёт после перегенерации ссылки?", search: "ключ что произойдёт после перегенерации ссылки? ключ что произойдёт после перегенерации ссылки? старая ссылка перестанет работать. на всех своих устройствах нужно удалить старый профиль и импортировать новый. используйте перегенерацию, если ссылка или qr-код попали к постороннему.", answer: "<p>Старая ссылка перестанет работать. На всех своих устройствах нужно удалить старый профиль и импортировать новый.<p>Используйте перегенерацию, если ссылка или QR-код попали к постороннему.</p></p>" },
  { id: "subscription-47", category: "subscription", tag: "Пробный", title: "Пробный период ограничивает серверы или скорость?", search: "пробный пробный период ограничивает серверы или скорость? пробный пробный период ограничивает серверы или скорость? пробный период предназначен для проверки совместимости. если часть серверов показывает n/a, чаще причина в сети, операторе или способе проверки пинга. точные условия и объём трафика смотрите в личном кабинете.", answer: "<p>Пробный период предназначен для проверки совместимости. Если часть серверов показывает N/A, чаще причина в сети, операторе или способе проверки пинга.<p>Точные условия и объём трафика смотрите в личном кабинете.</p></p>" },
  { id: "devices-48", category: "devices", tag: "Лимит", title: "Ошибка device limit reached или достигнут лимит устройств", search: "лимит ошибка device limit reached или достигнут лимит устройств лимит ошибка device limit reached или достигнут лимит устройств откройте личный кабинет. перейдите к списку устройств. удалите старые или неиспользуемые записи. убедитесь, что в клиенте включён hwid, если это требуется. обновите профиль и подключитесь. переустановка и смена клиента могут создать новую запись устройства.", answer: "<ol><li>Откройте личный кабинет.<li>Перейдите к списку устройств.<li>Удалите старые или неиспользуемые записи.<li>Убедитесь, что в клиенте включён HWID, если это требуется.<li>Обновите профиль и подключитесь.</li></li></li></li></li></ol><p>Переустановка и смена клиента могут создать новую запись устройства.</p>" },
  { id: "devices-49", category: "devices", tag: "Несколько", title: "Можно ли использовать один ключ на нескольких устройствах?", search: "несколько можно ли использовать один ключ на нескольких устройствах? несколько можно ли использовать один ключ на нескольких устройствах? да, в пределах лимита тарифа. точное число отображается в личном кабинете. не передавайте ключ посторонним: их устройства займут ваш лимит и получат доступ к подписке.", answer: "<p>Да, в пределах лимита тарифа. Точное число отображается в личном кабинете.<p>Не передавайте ключ посторонним: их устройства займут ваш лимит и получат доступ к подписке.</p></p>" },
  { id: "devices-50", category: "devices", tag: "Перенос", title: "Как перенести VPN на новый телефон или компьютер?", search: "перенос как перенести vpn на новый телефон или компьютер? перенос как перенести vpn на новый телефон или компьютер? если лимит заполнен, удалите старое устройство в кабинете. установите клиент на новом устройстве. возьмите актуальную ссылку из личного кабинета сайта или бота. импортируйте её, обновите профиль и проверьте серверы.", answer: "<ol><li>Если лимит заполнен, удалите старое устройство в кабинете.<li>Установите клиент на новом устройстве.<li>Возьмите актуальную ссылку из личного кабинета сайта или бота.<li>Импортируйте её, обновите профиль и проверьте серверы.</li></li></li></li></ol>" },
  { id: "devices-51", category: "devices", tag: "Раздача", title: "Будет ли VPN работать у устройств через точку доступа?", search: "раздача будет ли vpn работать у устройств через точку доступа? раздача будет ли vpn работать у устройств через точку доступа? обычная раздача интернета не всегда передаёт vpn-трафик подключённым устройствам. это зависит от системы и клиента. надёжнее установить клиент на каждом устройстве. в happ может использоваться режим локальной сети, но он требует отдельной настройки и одинаковой wi‑fi-сети.", answer: "<p>Обычная раздача интернета не всегда передаёт VPN-трафик подключённым устройствам. Это зависит от системы и клиента.<p>Надёжнее установить клиент на каждом устройстве. В Happ может использоваться режим локальной сети, но он требует отдельной настройки и одинаковой Wi‑Fi-сети.</p></p>" },
  { id: "tv-52", category: "tv", tag: "Android TV", title: "Как настроить Android TV или телевизор с Google TV?", search: "android tv как настроить android tv или телевизор с google tv? android tv как настроить android tv или телевизор с google tv? выберите tv-клиент на личной странице, обычно happ или flclashx. установите его из магазина tv либо официальным apk. передайте подписку qr-кодом, кодом привязки или через буфер — в зависимости от клиента. включите vpn и выберите сервер. не вводите длинную ссылку пультом, если приложение поддерживает qr или код.", answer: "<ol><li>Выберите TV-клиент на личной странице, обычно Happ или FlClashX.<li>Установите его из магазина TV либо официальным APK.<li>Передайте подписку QR-кодом, кодом привязки или через буфер — в зависимости от клиента.<li>Включите VPN и выберите сервер.</li></li></li></li></ol><p>Не вводите длинную ссылку пультом, если приложение поддерживает QR или код.</p>" },
  { id: "tv-53", category: "tv", tag: "Apple TV", title: "Как настроить Apple TV?", search: "apple tv как настроить apple tv? apple tv как настроить apple tv? установите совместимый клиент из app store apple tv. в некоторых версиях happ подписка передаётся с телефона в той же wi‑fi-сети через qr-код или локальное подключение. следуйте инструкции, показанной в приложении tv, и не публикуйте код привязки.", answer: "<p>Установите совместимый клиент из App Store Apple TV. В некоторых версиях Happ подписка передаётся с телефона в той же Wi‑Fi-сети через QR-код или локальное подключение.<p>Следуйте инструкции, показанной в приложении TV, и не публикуйте код привязки.</p></p>" },
  { id: "tv-54", category: "tv", tag: "Роутер", title: "Можно ли установить подписку на роутер?", search: "роутер можно ли установить подписку на роутер? роутер можно ли установить подписку на роутер? можно только на совместимом роутере и при наличии подходящего клиента/формата. это заметно сложнее обычной установки. не вставляйте зашифрованную ссылку happ в случайный конвертер. для дома безопаснее поставить клиент на устройства, а настройку роутера доверить специалисту.", answer: "<p>Можно только на совместимом роутере и при наличии подходящего клиента/формата. Это заметно сложнее обычной установки.<p>Не вставляйте зашифрованную ссылку Happ в случайный конвертер. Для дома безопаснее поставить клиент на устройства, а настройку роутера доверить специалисту.</p></p>" },
  { id: "settings-55", category: "settings", tag: "Доступ", title: "Работает ли сервис при режиме белых списков?", search: "доступ работает ли сервис при режиме белых списков? доступ работает ли сервис при режиме белых списков? на странице могут быть специальные серверы и правила для таких сетей. проверьте их доступность через http get и протестируйте в своей сети. результат зависит от оператора, региона и текущих ограничений, поэтому абсолютной гарантии для каждой sim-карты нет.", answer: "<p>На странице могут быть специальные серверы и правила для таких сетей. Проверьте их доступность через HTTP GET и протестируйте в своей сети.<p>Результат зависит от оператора, региона и текущих ограничений, поэтому абсолютной гарантии для каждой SIM-карты нет.</p></p>" },
  { id: "servers-56", category: "servers", tag: "Оператор", title: "Будет ли работать у моего оператора и в регионе?", search: "оператор будет ли работать у моего оператора и в регионе? оператор будет ли работать у моего оператора и в регионе? даже у одного оператора правила могут различаться по региону и типу сети. лучший способ — проверить пробный доступ на wi‑fi и мобильном интернете. если серверы не пингуются, сообщите поддержке оператора, регион, клиент и результаты http get.", answer: "<p>Даже у одного оператора правила могут различаться по региону и типу сети. Лучший способ — проверить пробный доступ на Wi‑Fi и мобильном интернете.<p>Если серверы не пингуются, сообщите поддержке оператора, регион, клиент и результаты HTTP GET.</p></p>" },
  { id: "servers-57", category: "servers", tag: "Геолокация", title: "Почему сайт показывает другую или неправильную страну?", search: "геолокация почему сайт показывает другую или неправильную страну? геолокация почему сайт показывает другую или неправильную страну? сайты определяют место по базам ip, которые обновляются не одновременно. страна сервера может отображаться с задержкой или соседним городом. смените сервер и очистите cookies сайта. gps телефона vpn не меняет.", answer: "<p>Сайты определяют место по базам IP, которые обновляются не одновременно. Страна сервера может отображаться с задержкой или соседним городом.<p>Смените сервер и очистите cookies сайта. GPS телефона VPN не меняет.</p></p>" },
  { id: "servers-58", category: "servers", tag: "Captcha", title: "Почему после VPN стало больше CAPTCHA?", search: "captcha почему после vpn стало больше captcha? captcha почему после vpn стало больше captcha? один сервер используют несколько пользователей, поэтому сайты могут чаще запрашивать проверку. смените сервер, подождите или войдите в аккаунт на нужном сайте. это не обязательно означает утечку или заражение устройства.", answer: "<p>Один сервер используют несколько пользователей, поэтому сайты могут чаще запрашивать проверку. Смените сервер, подождите или войдите в аккаунт на нужном сайте.<p>Это не обязательно означает утечку или заражение устройства.</p></p>" },
  { id: "errors-59", category: "errors", tag: "Банки", title: "Банковское или государственное приложение не работает с VPN", search: "банки банковское или государственное приложение не работает с vpn банки банковское или государственное приложение не работает с vpn некоторые локальные сервисы блокируют зарубежные ip. в режиме rule они обычно должны идти напрямую. сначала переключите сервер, затем временно отключите vpn для этой операции или добавьте приложение в direct/исключения. не используйте global постоянно.", answer: "<p>Некоторые локальные сервисы блокируют зарубежные IP. В режиме Rule они обычно должны идти напрямую.<p>Сначала переключите сервер, затем временно отключите VPN для этой операции или добавьте приложение в Direct/исключения. Не используйте Global постоянно.</p></p>" },
  { id: "security-60", category: "security", tag: "Ключ", title: "Можно ли отправить ключ другу или в общий чат?", search: "ключ можно ли отправить ключ другу или в общий чат? ключ можно ли отправить ключ другу или в общий чат? нет. ссылка даёт доступ к вашей подписке и занимает лимит устройств. при утечке перегенерируйте ключ. поддержке обычно достаточно скриншота ошибки без полной ссылки. закрывайте qr-код и адрес подписки.", answer: "<p>Нет. Ссылка даёт доступ к вашей подписке и занимает лимит устройств. При утечке перегенерируйте ключ.<p>Поддержке обычно достаточно скриншота ошибки без полной ссылки. Закрывайте QR-код и адрес подписки.</p></p>" },
  { id: "security-61", category: "security", tag: "Мошенники", title: "Какие данные никогда не должна просить поддержка?", search: "мошенники какие данные никогда не должна просить поддержка? мошенники какие данные никогда не должна просить поддержка? не передавайте пароль, telegram-код, sms-код, cvv, pin, seed-фразу и удалённый доступ к банковскому приложению. для диагностики нужны только модель устройства, версия системы и клиента, тип сети, текст ошибки и обезличенный скриншот.", answer: "<p>Не передавайте пароль, Telegram-код, SMS-код, CVV, PIN, seed-фразу и удалённый доступ к банковскому приложению.<p>Для диагностики нужны только модель устройства, версия системы и клиента, тип сети, текст ошибки и обезличенный скриншот.</p></p>" },
  { id: "security-62", category: "security", tag: "Логи", title: "Можно ли отправлять логи приложения?", search: "логи можно ли отправлять логи приложения? логи можно ли отправлять логи приложения? логи полезны, но могут содержать адрес подписки, uuid, ip и названия серверов. отправляйте их только в официальный канал поддержки. перед публикацией в общем чате удалите секретные строки и личные данные.", answer: "<p>Логи полезны, но могут содержать адрес подписки, UUID, IP и названия серверов. Отправляйте их только в официальный канал поддержки.<p>Перед публикацией в общем чате удалите секретные строки и личные данные.</p></p>" },
  { id: "start-63", category: "start", tag: "Удаление", title: "Как полностью удалить VPN и профиль?", search: "удаление как полностью удалить vpn и профиль? удаление как полностью удалить vpn и профиль? сначала отключите vpn и удалите подписку внутри клиента, затем удалите приложение. на iphone при необходимости проверьте настройки → основные → vpn и управление устройством. на компьютере отключите system proxy/tun перед удалением.", answer: "<p>Сначала отключите VPN и удалите подписку внутри клиента, затем удалите приложение.<p>На iPhone при необходимости проверьте Настройки → Основные → VPN и управление устройством. На компьютере отключите System Proxy/TUN перед удалением.</p></p>" },
  { id: "support-64", category: "support", tag: "Диагностика", title: "Что отправить поддержке, чтобы проблему решили быстрее?", search: "диагностика что отправить поддержке, чтобы проблему решили быстрее? диагностика что отправить поддержке, чтобы проблему решили быстрее? одним сообщением укажите: устройство и версию системы; название и версию клиента; wi‑fi или мобильную сеть, оператора и регион; точный текст ошибки; работает ли интернет без vpn; какие серверы пингуются; что уже попробовали. добавьте скриншот или короткое видео, скрыв ключ и qr-код.", answer: "<p>Одним сообщением укажите:<ul><li>устройство и версию системы;<li>название и версию клиента;<li>Wi‑Fi или мобильную сеть, оператора и регион;<li>точный текст ошибки;<li>работает ли интернет без VPN;<li>какие серверы пингуются;<li>что уже попробовали.</li></li></li></li></li></li></li></ul><p>Добавьте скриншот или короткое видео, скрыв ключ и QR-код.</p></p>" },
  { id: "apps-65", category: "apps", tag: "Версия", title: "Где посмотреть версию приложения?", search: "версия где посмотреть версию приложения? версия где посмотреть версию приложения? обычно версия указана в settings → about / о приложении. на телефоне её также можно посмотреть в карточке приложения в системных настройках. всегда сообщайте номер версии при ошибках импорта или xraycore.", answer: "<p>Обычно версия указана в Settings → About / О приложении. На телефоне её также можно посмотреть в карточке приложения в системных настройках.<p>Всегда сообщайте номер версии при ошибках импорта или xrayCore.</p></p>" },
];
